import { ensureError } from "../common/errorHelpers";
import { lensScriptError } from "../namedErrors";
import type { LensCoreError as NativeLensCoreError, LensCoreModule } from "./generated-types";

type ErrorName = `${string}Error`;
type NamedError<Name extends ErrorName> = Error & { name: Name; isFrameError: boolean };

export type LensCoreLensDeserializationError = NamedError<"LensCoreLensDeserializationError">;
export type LensCoreValidationError = NamedError<"LensCoreValidationError">;
export type LensCoreUncategorizedError = NamedError<"LensCoreUncategorizedError">;
export type LensCoreLensExecutionError = NamedError<"LensCoreLensExecutionError">;
export type LensCoreAbortError = NamedError<"LensCoreAbortError">;
export type LensCoreUninitializedError = NamedError<"LensCoreUninitializedError">;
export type LensCoreVideoPlaybackFailedError = NamedError<"LensCoreVideoPlaybackFailedError">;
export type LensCoreVideoPlaybackMutedError = NamedError<"LensCoreVideoPlaybackMutedError">;
export type LensCoreUnknownError = NamedError<"LensCoreUnknownError">;

export type LensCoreError =
    | LensCoreLensDeserializationError
    | LensCoreValidationError
    | LensCoreUncategorizedError
    | LensCoreLensExecutionError
    | LensCoreAbortError
    | LensCoreUninitializedError
    | LensCoreVideoPlaybackFailedError
    | LensCoreVideoPlaybackMutedError;

type NativeLensCoreErrorName = keyof LensCoreModule["ErrorType"];

// Construct a map linking each LensCore error name to its value,
// designed to trigger a compile-time error if an error is added or removed in LensCore.
// eslint-disable-next-line max-len
// https://github.sc-corp.net/Snapchat/LensCore/blob/285ac47cad7fe5268f38d1bab82d51b7b19d6b48/Src/PlatformSpecific/WebAssembly/ErrorType.hpp#L4
const lensCoreErrorValue: Record<NativeLensCoreErrorName, number> = {
    LensDeserialization: 0,
    Validation: 1,
    Uncategorized: 2,
    LensExecution: 3,
    Abort: 4,
    Uninitialized: 5,
    VideoPlaybackFailed: 6,
    VideoPlaybackMuted: 7,
};

// The purpose of lensCoreErrorValue above is to safeguard integrity.
// To achieve constant lookup times, we must swap the keys with their corresponding values.
const lensCoreErrorName = Object.fromEntries(
    Object.entries(lensCoreErrorValue).map((entry) => [entry[1], entry[0] as NativeLensCoreErrorName] as const)
);

// CoreJS appends the source-mapped lens stack to the exception text as "\nStack trace:\n<frames>", which LensCore
// forwards unchanged as the error message: "<message>\n\nStack trace:\n<fn>@<file>:<line>:<col>\n...".
// Non-script errors (validation, deserialization, native) never carry the marker.
const lensStackMarker = /^\s*Stack trace:\s*$/;

function nonEmptyLines(lines: string[]): string[] {
    return lines.map((line) => line.trimEnd()).filter((line) => line.length > 0);
}

// Chrome DevTools only renders V8-style frames ("    at fn (file:line:col)") when it prints an Error, and silently
// drops the "fn@file:line:col" lines the lens runtime produces. Firefox and Safari render either shape and error
// reporters parse both, so re-shape lens frames to the V8 form. The conversion is lossless.
function toV8Frame(frame: string): string {
    const at = frame.indexOf("@");
    if (at === -1) return `    at ${frame}`;
    const fn = frame.slice(0, at) || "<anonymous>";
    return `    at ${fn} (${frame.slice(at + 1)})`;
}

export function wrapLensCoreError(unknownError: unknown, isFrameError: boolean): LensCoreError {
    const lcError = ensureError(unknownError) as NativeLensCoreError;
    const lines = lcError.message.split(/\r?\n/);
    const message = lines[0];
    const markerIdx = lines.findIndex((line) => lensStackMarker.test(line));
    const lensStackLines = markerIdx === -1 ? [] : nonEmptyLines(lines.slice(markerIdx + 1));
    const lcCause =
        lcError.otherExceptions || lcError.cause?.metadata
            ? { otherExceptions: lcError.otherExceptions, metadata: lcError.cause?.metadata }
            : undefined;
    const error = new Error(message) as LensCoreError;
    const lcErrorType = lcError.cause?.type?.value;
    const name: (LensCoreError | LensCoreUnknownError)["name"] = `LensCore${
        lensCoreErrorName[lcErrorType] ?? "Unknown"
    }Error` as const;
    error.name = name;
    error.isFrameError = isFrameError;

    // This error keeps LensCore's own backtrace (the WASM catch site). LensCore's Backtrace::format() leaves the
    // C-string terminator on it, and the backtrace may be headerless (Emscripten, Firefox/Safari), so strip the
    // first line only when it is a "Name" / "Name: message" header, never a frame.
    const header = message ? `${name}: ${message}` : name;
    const stackLines = nonEmptyLines((lcError.stack ?? "").replace(/\0+$/, "").split(/\r?\n/));
    const firstLine = stackLines[0];
    const frames =
        firstLine === lcError.name || firstLine?.startsWith(`${lcError.name}:`) ? stackLines.slice(1) : stackLines;
    error.stack = [header, ...frames].join("\n");

    if (lensStackLines.length > 0) {
        // The lens script failure becomes the innermost cause, carrying the lens's own message and frames.
        const scriptError = lensScriptError(message, lcCause);
        scriptError.stack = [
            message ? `LensScriptError: ${message}` : "LensScriptError",
            ...lensStackLines.map(toV8Frame),
        ].join("\n");
        error.cause = scriptError;
    } else if (lcCause) {
        error.cause = lcCause;
    }
    return error;
}
